          {accountHistory.map(x=><tr key={x.id}><td style={{...td,maxWidth:170,overflow:"hidden",textOverflow:"ellipsis"}}>{x.id}</td><td style={td}>{money(x.amountMinor,x.currency)}</td><td style={td}><Pill value={stateText(x.status)}/></td><td style={td}>{x.payoutReference||"—"}</td><td style={td}>{date(x.createdAt)}</td></tr>)}
          {!accountHistory.length&&<tr><td colSpan={5} style={{padding:28,textAlign:"center",color:"#8492a6",fontSize:12}}>暂无关联提现记录</td></tr>}
