  {adjustmentOpen&&<div style={{position:"fixed",inset:0,zIndex:95,background:"#14223866",display:"grid",placeItems:"center",padding:18}}><section style={{...box,width:"min(560px,100%)",padding:18,boxShadow:"0 18px 55px #14223830"}}><header style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div><b style={{fontSize:15,color:"#20334d"}}>新建任务调账</b><p style={{fontSize:11,color:"#718096",margin:"5px 0 0"}}>提交后将立即写入钱包流水，并记录管理员审计信息。</p></div><button style={btn} onClick={()=>setAdjustmentOpen(false)}>关闭</button></header><div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:11}}><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c",gridColumn:"1 / -1"}}>用户手机号或用户 ID *<input style={input} value={adjustmentForm.user} onChange={e=>setAdjustmentForm(v=>({...v,user:e.target.value}))} placeholder="输入用户手机号或 UUID"/></label><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c"}}>币种 *<select style={input} value={adjustmentForm.currency} onChange={e=>setAdjustmentForm(v=>({...v,currency:e.target.value}))}>{["KES","USD","NGN","PKR","BDT"].map(x=><option key={x}>{x}</option>)}</select></label><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c"}}>调账金额 *<input style={input} type="number" min="0.01" step="0.01" value={adjustmentForm.amount} onChange={e=>setAdjustmentForm(v=>({...v,amount:e.target.value}))} placeholder="0.00"/></label><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c"}}>调账方向 *<select style={input} value={adjustmentForm.direction} onChange={e=>setAdjustmentForm(v=>({...v,direction:e.target.value}))}><option value="CREDIT">增加余额</option><option value="DEBIT">扣减余额</option></select></label><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c"}}>关联任务名称（选填）<input style={input} value={adjustmentForm.taskTitle} onChange={e=>setAdjustmentForm(v=>({...v,taskTitle:e.target.value}))} placeholder="关联任务说明"/></label><label style={{display:"grid",gap:5,fontSize:11,color:"#53647c",gridColumn:"1 / -1"}}>操作原因 *<textarea style={{...input,height:88,padding:9,resize:"vertical"}} maxLength={500} value={adjustmentForm.reason} onChange={e=>setAdjustmentForm(v=>({...v,reason:e.target.value}))} placeholder="请填写调账原因，最多 500 个字符"/></label></div><p style={{fontSize:10,color:"#b45309",background:"#fff8eb",padding:9,borderRadius:6,lineHeight:1.6,marginTop:12}}>注意：调账提交后立即生效，不可直接撤销。扣减操作会校验可用余额，不能扣成负数。</p><footer style={{display:"flex",justifyContent:"flex-end",gap:8,marginTop:12}}><button style={btn} onClick={()=>setAdjustmentOpen(false)}>取消</button><button style={{...btn,background:"#2868ee",color:"#fff",borderColor:"#2868ee"}} disabled={adjustmentSaving} onClick={()=>void saveAdjustment()}>{adjustmentSaving?"提交中…":"确认调账"}</button></footer></section></div>}
  {reconciliationDetail&&<div style={{position:"fixed",inset:0,zIndex:96,background:"#14223866",display:"grid",placeItems:"center",padding:18}}><section style={{...box,width:"min(900px,100%)",maxHeight:"90vh",overflowY:"auto",padding:16,boxShadow:"0 18px 55px #14223830"}}><header style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}><div><b style={{fontSize:15,color:"#20334d"}}>{reconciliationDetail.title||"财务对账运行详情"}</b><p style={{fontSize:10,color:"#8492a6",margin:"5px 0 0"}}>{reconciliationDetail.id}</p></div><button style={btn} onClick={()=>setReconciliationDetail(null)}>关闭</button></header>{reconciliationDetail.items&&<><div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:8,marginBottom:12}}>{[["运行状态",reconciliationDetail.status==="SUCCESS"?"成功":reconciliationDetail.status==="INCOMPLETE"?"扫描不完整":reconciliationDetail.status==="FAILED"?"发现异常":reconciliationDetail.status||"—"],["检查数",String(reconciliationDetail.checkedCount??0)],["异常数",String(reconciliationDetail.exceptionCount??0)]].map(([k,v])=><div key={k} style={{border:"1px solid #e4eaf2",borderRadius:6,padding:10}}><div style={{fontSize:10,color:"#8492a6"}}>{k}</div><b style={{fontSize:16,color:"#20334d"}}>{v}</b></div>)}</div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}><thead><tr>{["异常类型","记录 ID","用户 / 任务","金额","问题说明"].map(x=><th style={th} key={x}>{x}</th>)}</tr></thead><tbody>{(reconciliationDetail.items as Row[]).map((x:Row,i:number)=><tr key={x.recordId||i}><td style={td}>{x.type}</td><td style={{...td,maxWidth:180,overflow:"hidden",textOverflow:"ellipsis"}}>{x.recordId||"—"}</td><td style={{...td,whiteSpace:"normal"}}>{x.user||x.task||x.providerCode||"—"}</td><td style={td}>{x.amountMinor?money(x.amountMinor,x.currency):"—"}</td><td style={{...td,whiteSpace:"normal",minWidth:240}}>{x.message}{x.expectedAmountMinor!==undefined&&<div style={{fontSize:10,color:"#718096",marginTop:4}}>预期：{x.expectedAmountMinor} {x.expectedCurrency||""}；实际：{x.actualAmountMinor??"—"} {x.actualCurrency||""} {x.actualDirection||""}</div>}</td></tr>)}{!(reconciliationDetail.items as Row[]).length&&<tr><td colSpan={5} style={{padding:26,textAlign:"center",color:"#15945b"}}>本次检查未发现异常</td></tr>}</tbody></table></div></>}{!reconciliationDetail.items&&<div style={{fontSize:12,color:"#53647c",lineHeight:1.8}}>用户：{reconciliationDetail.phone||"—"}<br/>任务：{reconciliationDetail.taskTitle||"—"}<br/>任务提交 ID：{reconciliationDetail.id||"—"}<br/>金额：{reconciliationDetail.amountMinor?money(reconciliationDetail.amountMinor,reconciliationDetail.currency):"—"}<br/>方向：{reconciliationDetail.direction==="CREDIT"?"增加余额":reconciliationDetail.direction==="DEBIT"?"扣减余额":"—"}<br/>操作原因：{reconciliationDetail.reason||"—"}<br/>管理员：{reconciliationDetail.adminId||"—"}<br/>创建时间：{reconciliationDetail.createdAt?date(reconciliationDetail.createdAt):"—"}</div>}</section></div>}
