<div style={{padding:"10px 0",borderBottom:"1px solid #e8edf4"}}><b style={{fontSize:13,color:"#24364d"}}>{providerCatalogs.countries.find(x=>x.code===providerForm.countryCode)?.name||providerForm.countryCode||"未选择国家"} · {providerForm.methodCode||"未设置业务方式"}</b><div style={{fontSize:11,color:"#718096",marginTop:4}}>到账币种：{providerForm.supportedCurrencies||"未配置"}</div></div>
